import { cookies, headers } from 'next/headers'

function preferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) {
    return 'not specified'
  }

  const primary = acceptLanguage.split(',')[0]?.split(';')[0]?.trim()
  return primary || 'not specified'
}

export default async function UserPreferences() {
  const cookieStore = await cookies()
  const theme = cookieStore.get('theme')?.value || 'light'

  const acceptLanguage = (await headers()).get('accept-language')
  const language = preferredLanguage(acceptLanguage)

  return (
    <section>
      <p>Current theme: {theme}</p>
      <p>Preferred language: {language}</p>
    </section>
  )
}

